def get_stock(symbol):
    return {'MSFT': 100.0, 'AAPL': 90.0}[symbol]

def convert(amount, rate):
    return amount * rate

REGISTRY = {
    'get_stock': {'fn': get_stock, 'required': ['symbol']},
    'convert': {'fn': convert, 'required': ['amount', 'rate']},
}

def dispatch(call):
    tool = REGISTRY[call['name']]
    args = call['args']
    for name in tool['required']:
        if name not in args:
            return f"ERROR: missing required arg '{name}'"
    return tool['fn'](**args)

calls = [
    {'name': 'get_stock', 'args': {'symbol': 'MSFT'}},
    {'name': 'convert', 'args': {'amount': 100.0, 'rate': 2.0}},
    {'name': 'get_stock', 'args': {}},
]

ok = 0
failed = 0
for call in calls:
    result = dispatch(call)
    print(f"{call['name']}({call['args']}) -> {result}")
    if isinstance(result, str) and result.startswith('ERROR'):
        failed += 1
    else:
        ok += 1

print(f'Dispatched: {ok} ok, {failed} failed')
